import {createOperationStatus,nextPaint} from './operation-status.js';
import {getTimeline} from './project.js';
import {assist,displayScript,deliverySourceKey} from './production-delivery-utils.js';
import {normalizeProductionAssistantResult} from './production-assistant-protocol.js';
import {mediaSearchClient} from './media-search-client.js';
import {normalizeMusicState,mediaAttributionText} from './media-search-protocol.js';
const node=(tag,className='',text)=>{const value=document.createElement(tag);value.className=className;if(text!==undefined)value.textContent=text;return value;};
const button=(id,text,kind='outline')=>{const value=node('button',kind,text);value.id=id;value.type='button';return value;};
const scope=api=>({projectId:api.getProject().id,workspaceId:api.getWorkspaceId?.()??null});
const owns=(api,target)=>target?.projectId===api.getProject().id&&(target.workspaceId??null)===(api.getWorkspaceId?.()??null);
const key=value=>JSON.stringify([value.projectId,value.workspaceId]);
function link(text,url){const el=node('a','',text);el.href=url;el.target='_blank';el.rel='noopener noreferrer';return el;}
async function copy(value){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);return;}const box=node('textarea');box.value=value;document.body.append(box);box.select();const ok=document.execCommand('copy');box.remove();if(!ok)throw new Error('출처를 복사하지 못했어요. 자료의 출처 링크에서 확인하세요.');}
const time=seconds=>{const total=Math.round(seconds);return`${Math.floor(total/60)}:${String(total%60).padStart(2,'0')}`;};

/** Recommendations describe a style; playable choices always come from a real public catalog. */
export function setupMusicRecommendations(api){
 const host=document.getElementById('bgmDrop');if(!host)throw new Error('배경음악 추천 위치를 찾지 못했어요.');
 if(!document.getElementById('musicRecommendationsStyles')){const style=node('link');style.id='musicRecommendationsStyles';style.rel='stylesheet';style.href=new URL('./music-recommendations.css',import.meta.url).href;document.head.append(style);}
 const launcher=button('musicRecommendationsBtn','배경음악 추천');host.querySelector('.bgm-controls')?.append(launcher);
 const dialog=node('dialog','modal music-recommendations-modal');dialog.id='musicRecommendationsDialog';dialog.setAttribute('aria-labelledby','musicRecommendationsTitle');
 const heading=node('div','dialog-heading'),titles=node('div');titles.append(node('span','eyebrow','MUSIC FOR YOUR STORY'));const title=node('h2','','영상에 맞는 배경음악');title.id='musicRecommendationsTitle';titles.append(title);const close=button('closeMusicRecommendationsHeaderBtn','×','icon-button');close.setAttribute('aria-label','배경음악 추천 닫기');heading.append(titles,close);dialog.append(heading);
 const body=node('div','dialog-body');body.append(node('p','music-help','대본·장면의 내용으로 음악 분위기를 추천하고 Wikimedia Commons의 실제 음원을 찾아요. 미리 듣고 출처·이용 조건을 확인한 뒤 사용할 음악을 고르세요.'));
 const actions=node('div','music-actions'),recommend=button('recommendMusicBtn','영상 내용 분석·음악 추천','primary'),settings=button('musicApiSettingsBtn','AI 설정','ghost'),cancel=button('cancelMusicRecommendationBtn','작업 취소','ghost');cancel.hidden=true;actions.append(recommend,settings,cancel);body.append(actions);
 const searchLabel=node('label','music-query');searchLabel.htmlFor='musicSearchQuery';searchLabel.append(node('span','','실제 음원 검색어'));const query=node('input');query.id='musicSearchQuery';query.maxLength=500;query.placeholder='예: ambient instrumental, piano calm, orchestral';searchLabel.append(query);const search=button('searchMusicBtn','음원 찾기');body.append(searchLabel,search,node('p','music-help','직접 음원 검색에는 AI 키가 필요하지 않아요. 추천 제목은 음악 방향이며, 아래 실제 음원과 구분해 표시해요.'));
 const operation=createOperationStatus({container:body,region:dialog,id:'musicRecommendationOperation'}),status=node('p','music-status'),error=node('p','music-error');status.id='musicRecommendationStatus';status.setAttribute('role','status');error.id='musicRecommendationError';error.setAttribute('role','alert');body.append(status,error);
 const suggestions=node('section','music-suggestions');suggestions.id='musicStyleSuggestions';body.append(suggestions);
 const player=node('audio');player.id='musicPreviewAudio';player.controls=true;player.preload='none';player.crossOrigin='anonymous';player.hidden=true;body.append(player);
 const results=node('section','music-results');results.id='musicSearchResults';body.append(results);
 const applied=node('section','music-applied');applied.id='musicAppliedCredit';body.append(applied);
 const footer=node('div','dialog-footer'),done=button('closeMusicRecommendationsBtn','닫기','ghost');footer.append(done);dialog.append(body,footer);document.body.append(dialog);
 const client=api.mediaSearchClient||mediaSearchClient;
 let owner='',fingerprint='',suggestionsKey='',resultsKey='',appliedKey='',busy='',controller=null,sequence=0,saving=false,lastFocus=null,disposed=false;
 const current=()=>normalizeMusicState(api.getProject().production?.music||{});
 function mutate(action){saving=true;try{(api.mutateProductionMetadata||api.mutate)(project=>{project.production||={version:1};const value=normalizeMusicState(project.production.music||{});action(value);project.production.music=normalizeMusicState(value);});}finally{saving=false;}render();}
 function canEdit(){return !busy&&(!api.canMutate||api.canMutate());}
 function refresh(){const ready=canEdit();launcher.disabled=!ready;recommend.disabled=search.disabled=settings.disabled=query.disabled=!ready;cancel.hidden=!busy;for(const el of body.querySelectorAll('[data-music-action]'))el.disabled=!ready;}
 function stop(message='음악 추천 작업을 취소했어요. 이전 추천과 배경음악은 유지돼요.'){sequence++;controller?.abort();controller=null;if(busy)operation.cancel(message);busy='';refresh();}
 function stopPlayer(){player.pause();player.removeAttribute('src');player.load();player.hidden=true;}
 function creditRow(item){const line=node('p','music-meta');line.append(link('원본·저작자·출처',item.sourceUrl),document.createTextNode(` · ${item.artist||'저작자 정보 확인'} · Commons 표기: ${item.license||'출처에서 이용 조건 확인'}`));if(item.licenseUrl)line.append(document.createTextNode(' · '),link('이용 조건',item.licenseUrl));return line;}
 function draw(state){
  const next=JSON.stringify(state.recommendations);if(next!==suggestionsKey){suggestionsKey=next;suggestions.replaceChildren();if(state.recommendations.length)suggestions.append(node('h3','','AI가 추천한 음악 방향'));for(const item of state.recommendations){const card=node('article','music-style-card');card.append(node('strong','',item.title),node('p','music-help',[item.mood,item.style,item.instruments.join(' · '),item.tempoBpm?`${item.tempoBpm} BPM 제안`:''].filter(Boolean).join(' / ')),node('p','music-help',item.reason));const find=button('',`이 분위기의 실제 음원 찾기`);find.dataset.musicAction='search';find.addEventListener('click',()=>{query.value=item.searchQuery;runSearch(item.searchQuery);});card.append(find);suggestions.append(card);}}
  const list=JSON.stringify(state.candidates);if(list!==resultsKey){resultsKey=list;results.replaceChildren();if(state.candidates.length)results.append(node('h3','','실제 음원 · 듣고 선택'));for(const item of state.candidates){const card=node('article','music-track-card');card.dataset.musicId=item.id;card.append(node('strong','',item.title),node('p','music-help',[item.duration?time(item.duration):'',item.description].filter(Boolean).join(' · ')),creditRow(item));const row=node('div','music-actions'),play=button('', '미리 듣기'),use=button('', '이 음악을 배경음악으로 사용','primary'),credit=button('','출처 표시 복사','ghost');play.dataset.musicAction='preview';use.dataset.musicAction='apply';credit.dataset.musicAction='credit';row.append(play,use,credit);card.append(row);results.append(card);play.addEventListener('click',()=>preview(item));use.addEventListener('click',()=>apply(item));credit.addEventListener('click',()=>copy(mediaAttributionText(item)).then(()=>{status.textContent='이 음악의 출처 표시를 복사했어요.';}).catch(cause=>{error.textContent=cause.message;}));}}
  const selected=JSON.stringify(state.appliedCandidate);if(selected!==appliedKey){appliedKey=selected;applied.replaceChildren();if(state.appliedCandidate){applied.append(node('h3','','프로젝트에 보관한 음악 출처'),node('strong','',state.appliedCandidate.title),creditRow(state.appliedCandidate));const credit=button('copyAppliedMusicCreditBtn','보관한 음악 출처 복사');credit.addEventListener('click',()=>copy(mediaAttributionText(current().appliedCandidate)).then(()=>{status.textContent='보관한 음악의 출처 표시를 복사했어요.';}).catch(cause=>{error.textContent=cause.message;}));applied.append(credit);}}
 }
 function render(){if(disposed)return;const nextOwner=key(scope(api));if(nextOwner!==owner){stop('프로젝트가 바뀌어 음악 작업을 중지했어요.');stopPlayer();owner=nextOwner;fingerprint=suggestionsKey=resultsKey=appliedKey='';error.textContent='';status.textContent='';operation.clear();}const state=current(),next=JSON.stringify(state);if(!saving&&next!==fingerprint){fingerprint=next;if(document.activeElement!==query&&!busy)query.value=state.query;draw(state);}refresh();}
 function open(){lastFocus=document.activeElement;render();if(!dialog.open)dialog.showModal();query.focus();}
 async function runSearch(value){if(busy)return;const text=String(value??query.value).trim();if(!text){error.textContent='찾을 음악의 분위기나 장르를 입력해 주세요.';return;}const target=scope(api),seq=++sequence;controller=new AbortController();busy='search';error.textContent='';query.value=text;const job=operation.start('Wikimedia Commons에서 실제 음원을 찾고 있어요.');refresh();try{const candidates=await client.search(text,{kind:'audio',signal:controller.signal});if(seq!==sequence||!owns(api,target))return;mutate(state=>{state.query=text;state.candidates=candidates;state.selectedId='';state.searchedAt=new Date().toISOString();});await api.persist?.();if(seq===sequence&&owns(api,target)){status.textContent=candidates.length?`${candidates.length}개 실제 음원을 찾았어요. 재생해서 확인한 뒤 골라 주세요.`:'검색 결과가 없어요. ambient, piano, instrumental 등 넓은 검색어를 사용해 보세요.';job.finish('실제 음원 검색을 마쳤어요.');}}catch(cause){if(seq!==sequence||!owns(api,target))return;cause.name==='AbortError'?job.cancel('음원 검색을 취소했어요.'):(error.textContent=cause.message,job.fail(cause.message));}finally{if(seq===sequence){controller=null;busy='';refresh();}}}
 async function recommendForStory(){if(busy)return;const project=api.getProject(),fullScript=(api.getDisplayScript?.()||displayScript(project)||project.scenes.map(item=>item.caption).join('\n\n')).trim();if(!fullScript){error.textContent='대본이나 장면 내용을 먼저 준비해 주세요. 직접 음원 검색은 바로 사용할 수 있어요.';return;}const target=scope(api),sourceKey=deliverySourceKey(project),seq=++sequence;controller=new AbortController();busy='recommend';error.textContent='';const job=operation.start('대본과 장면 내용으로 음악 분위기를 분석하고 있어요.');refresh();try{await nextPaint();const timeline=getTimeline(project),context={title:project.title,fullScript,durationSeconds:timeline.duration,scenes:timeline.scenes.map(({id,start,end,caption})=>({id,start,end,caption})),channel:project.production?.channel?.name||'',tone:project.production?.channel?.tone||''};const raw=await assist('music-recommendations',context,{},controller.signal),value=normalizeProductionAssistantResult('music-recommendations',raw,{task:'music-recommendations',context,options:{}});if(seq!==sequence||!owns(api,target)||sourceKey!==deliverySourceKey(api.getProject())){job.cancel('대본이나 프로젝트가 바뀌어 이전 음악 추천을 적용하지 않았어요.');return;}mutate(state=>{state.recommendations=value.recommendations;state.suggestedAt=new Date().toISOString();});if(value.recommendations.length){const searchQuery=value.recommendations[0].searchQuery;query.value=searchQuery;job.update('추천한 분위기에 맞는 실제 음원을 찾고 있어요.');const candidates=await client.search(searchQuery,{kind:'audio',signal:controller.signal});if(seq!==sequence||!owns(api,target)||sourceKey!==deliverySourceKey(api.getProject()))return;mutate(state=>{state.query=searchQuery;state.candidates=candidates;state.selectedId='';state.searchedAt=new Date().toISOString();});status.textContent=candidates.length?`${value.recommendations.length}개 음악 방향과 ${candidates.length}개 실제 음원을 찾았어요.`:'추천 방향을 보관했어요. 실제 음원 결과가 없으니 다른 추천 방향 또는 검색어를 선택하세요.';}await api.persist?.();if(seq===sequence&&owns(api,target))job.finish('음악 추천을 마쳤어요. 들어보고 사용할 음악을 선택하세요.');}catch(cause){if(seq!==sequence||!owns(api,target))return;cause.name==='AbortError'?job.cancel('음악 추천을 취소했어요.'):(error.textContent=cause.message,job.fail(cause.message));}finally{if(seq===sequence){controller=null;busy='';refresh();}}}
 function preview(item){if(busy)return;error.textContent='';mutate(state=>{state.selectedId=item.id;});player.hidden=false;player.src=item.previewUrl||item.mediaUrl;player.play().catch(()=>{error.textContent='이 음원을 미리 재생하지 못했어요. 출처에서 확인하거나 다른 음원을 골라 주세요.';});}
 async function apply(item){if(busy)return;const target=scope(api),seq=++sequence;controller=new AbortController();busy='apply';error.textContent='';const job=operation.start('선택한 실제 음악 파일을 가져오고 있어요.');refresh();try{const file=await client.download(item,{signal:controller.signal});if(seq!==sequence||!owns(api,target))return;job.update('음악을 읽고 배경음악으로 적용하고 있어요.');await api.addBgmFile(file);if(seq!==sequence||!owns(api,target))return;mutate(state=>{state.selectedId=item.id;state.appliedCandidate=item;});await api.persist?.();job.finish('배경음악으로 적용했어요. 출처도 프로젝트에 보관했어요.');status.textContent='선택한 음악을 배경음악으로 넣었어요. 편집기에서 음량·반복·구간을 조절할 수 있어요.';api.toast?.('추천 음원을 배경음악으로 적용했어요.');}catch(cause){if(seq!==sequence||!owns(api,target))return;cause.name==='AbortError'?job.cancel('음악 가져오기를 취소했어요.'):(error.textContent=cause.message,job.fail(cause.message));}finally{if(seq===sequence){controller=null;busy='';refresh();}}}
 launcher.addEventListener('click',open);search.addEventListener('click',()=>runSearch(query.value));recommend.addEventListener('click',recommendForStory);cancel.addEventListener('click',()=>stop());settings.addEventListener('click',()=>api.openApiSettings?.());query.addEventListener('input',()=>{if(busy==='search')stop('검색어가 바뀌어 이전 음원 검색을 중지했어요.');});
 player.addEventListener('error',()=>{if(player.src)error.textContent='이 음원을 재생하지 못했어요. 출처에서 확인하거나 다른 음원을 골라 주세요.';});for(const el of[close,done])el.addEventListener('click',()=>dialog.close());dialog.addEventListener('cancel',()=>stop());dialog.addEventListener('close',()=>{stop();stopPlayer();if(lastFocus?.isConnected)lastFocus.focus();});
 window.addEventListener('studio-api-settings-change',()=>{if(busy==='recommend')stop('AI 설정이 바뀌어 음악 추천을 중지했어요. 기존 추천과 배경음악은 유지돼요.');});
 render();return{render,open,flush(){},reset(){stop('');stopPlayer();owner='';if(dialog.open)dialog.close();render();},onClose(){stop();stopPlayer();},getBusy:()=>Boolean(busy),dispose(){disposed=true;stop('');stopPlayer();operation.dispose();dialog.remove();launcher.remove();}};
}
